package com.bank.ebs;

import java.util.logging.*;

public class EbsAdvisorDemo {
    private static final Logger log = Logger.getLogger("EBS");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        VolumeAdvisor advisor = new VolumeAdvisor();

        EbsVolume reportingGp2 = new EbsVolume("gp2", 100, 0);
        EbsVolume reportingGp3 = new EbsVolume("gp3", 100, 6000);

        int required = 3000;
        log.info(() -> "Reporting on gp2 (100 GiB): effective IOPS = " + advisor.effectiveIops(reportingGp2));
        log.warning(() -> "gp2 gives only " + advisor.effectiveIops(reportingGp2)
                + " IOPS but we need " + required + " — would need to over-provision size");
        log.info(() -> "Reporting on gp3 (100 GiB): effective IOPS = " + advisor.effectiveIops(reportingGp3)
                + " (decoupled from size, ~20% cheaper)");

        log.info(() -> "Recommendation for reporting: " + advisor.recommend(required, false));
        log.info(() -> "Recommendation for core ledger (needs consistency): "
                + advisor.recommend(50000, true));
    }
}

// ─── Would be in VolumeAdvisor.java ───
class VolumeAdvisor {
    // gp2 IOPS is locked to 3 per GiB; gp3 uses baseline 3000 or provisioned IOPS.
    int effectiveIops(EbsVolume v) {
        return switch (v.type()) {
            case "gp2" -> v.sizeGiB() * 3;
            case "gp3" -> Math.max(3000, v.provisionedIops());
            case "io1", "io2" -> v.provisionedIops();
            default -> 0; // st1/sc1 measured by throughput, not IOPS
        };
    }

    String recommend(int requiredIops, boolean needsConsistency) {
        if (needsConsistency || requiredIops > 16000) {
            return "io2 (provisioned IOPS, highest + consistent performance)";
        }
        return "gp3 (3000 IOPS baseline, raise IOPS/throughput independently, cheaper than gp2)";
    }
}

// ─── Would be in EbsVolume.java ───
class EbsVolume {
    private final String type;
    private final int sizeGiB;
    private final int provisionedIops;
    EbsVolume(String type, int sizeGiB, int provisionedIops) {
        this.type = type; this.sizeGiB = sizeGiB; this.provisionedIops = provisionedIops;
    }
    String type() { return type; }
    int sizeGiB() { return sizeGiB; }
    int provisionedIops() { return provisionedIops; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
